// MinimockScheduleCleanupDone returns true if the count of the ScheduleCleanup invocations corresponds
// the number of defined expectations
func (m *CopyRepositoryMock) MinimockScheduleCleanupDone() bool {
	if m.ScheduleCleanupMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.ScheduleCleanupMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.ScheduleCleanupMock.invocationsDone()
}

// MinimockScheduleCleanupInspect logs each unmet expectation
func (m *CopyRepositoryMock) MinimockScheduleCleanupInspect() {
	for _, e := range m.ScheduleCleanupMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to CopyRepositoryMock.ScheduleCleanup at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterScheduleCleanupCounter := mm_atomic.LoadUint64(&m.afterScheduleCleanupCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ScheduleCleanupMock.defaultExpectation != nil && afterScheduleCleanupCounter < 1 {
		if m.ScheduleCleanupMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to CopyRepositoryMock.ScheduleCleanup at\n%s", m.ScheduleCleanupMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to CopyRepositoryMock.ScheduleCleanup at\n%s with params: %#v", m.ScheduleCleanupMock.defaultExpectation.expectationOrigins.origin, *m.ScheduleCleanupMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcScheduleCleanup != nil && afterScheduleCleanupCounter < 1 {
		m.t.Errorf("Expected call to CopyRepositoryMock.ScheduleCleanup at\n%s", m.funcScheduleCleanupOrigin)
	}

	if !m.ScheduleCleanupMock.invocationsDone() && afterScheduleCleanupCounter > 0 {
		m.t.Errorf("Expected %d calls to CopyRepositoryMock.ScheduleCleanup at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ScheduleCleanupMock.expectedInvocations), m.ScheduleCleanupMock.expectedInvocationsOrigin, afterScheduleCleanupCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *CopyRepositoryMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockGetByMigrationInspect()

			m.MinimockInsertOrphansInspect()

			m.MinimockInsertSourceInspect()

			m.MinimockInsertTargetInspect()

			m.MinimockListByMigrationInspect()

			m.MinimockListDueCleanupsInspect()

			m.MinimockLockByIDInspect()

			m.MinimockLockByMigrationInspect()

			m.MinimockMarkCleanupFailedInspect()

			m.MinimockMarkDeletedInspect()

			m.MinimockPromoteInspect()

			m.MinimockScheduleCleanupInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *CopyRepositoryMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *CopyRepositoryMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockGetByMigrationDone() &&
		m.MinimockInsertOrphansDone() &&
		m.MinimockInsertSourceDone() &&
		m.MinimockInsertTargetDone() &&
		m.MinimockListByMigrationDone() &&
		m.MinimockListDueCleanupsDone() &&
		m.MinimockLockByIDDone() &&
		m.MinimockLockByMigrationDone() &&
		m.MinimockMarkCleanupFailedDone() &&
		m.MinimockMarkDeletedDone() &&
		m.MinimockPromoteDone() &&
		m.MinimockScheduleCleanupDone()
}
